export function carryCap(world: World, p: Person): number {
const st = stageOf(world, p);
// an elder carries less in a rich world (elderFactor is 1 otherwise, and for everyone else)
const base = st === 'elder' ? Math.round(CARRY_CAP[st] * elderFactor(world, p)) : CARRY_CAP[st];
return base + ((p.inv.basket ?? 0) > 0 ? BASKET_BONUS : 0);
}

export function weightOf(items: Items): number {
let w = 0;
for (const k in items) w += (items[k as ItemKind] ?? 0) * WEIGHT[k as ItemKind];
// a water jar carries its first few units of water without making the load heavier

export function roomFor(items: Items, cap: number, k: ItemKind): number {
return Math.max(0, Math.floor((cap - weightOf(items) + 1e-9) / WEIGHT[k]));
}

export function drive(level: number, key: NeedKey, world?: World): number {
let [t1, t2] = DRIVE_BANDS[key];
// version 9: people tolerate a little cold before the warmth drive starts (a band 46 -> 26 instead of 52 -> 30)
if (world && key === 'warmth' && runsRulesVersion(world, 9)) [t1, t2] = [46, 26];
if (level >= t1) return 0;
if (level >= t2) return (60 * (t1 - level)) / (t1 - t2);
return 60 + (40 * (t2 - Math.max(0, level))) / t2;
}

export function pen(etaTicks: number): number {
return etaTicks * 0.07;
}

export function eta(ctx: Ctx, x: number, y: number): number {
return (hyp(x - ctx.p.x, y - ctx.p.y) * 1.18) / Math.max(0.03, ctx.speed);
}

export function foodUnits(items: Items): number {
let n = 0;
for (const k of FOOD_ORDER) n += items[k] ?? 0;
return n;
}

export function rationHeld(w: World, carried: number, hunger: number, foodKnownAtHome: boolean, etaHome: number): boolean {
return hasRation(w) && carried > 0 && carried <= RATION_KEEP && foodKnownAtHome && hunger > RATION_HUNGER && etaHome <= RATION_REACH;
}

export function rationApplies(w: World, isChild: boolean): boolean {
return hasRation(w) && !(isChild && childrenExempt && runsRulesVersion(w, 208));
}

export function mealLeaves(w: World, carriedBefore: number, isChild = false): number {
return rationApplies(w, isChild) ? Math.min(Math.max(0, carriedBefore), rationPortions(w)) : 0;
}

